import * as React from "react";
import TextField from "../textField/TextField";
import IconButton from "../iconButton/IconButton";

export interface SearchBarProps {
    className: string,
    buttonClassName: string
}


const SearchBar: React.FC<SearchBarProps> = ({ className, buttonClassName }) => {
    
    return (
        <div className={`${className}`}>
            <TextField  type="text"  placeholder={"How can we help you?"}/>
            <div className="search-bar-btn">
              <IconButton id={"iconButtonID"} className={`${buttonClassName}`} icon={'Search'} btnType={"standard"} ></IconButton>
            </div>
        </div> 
        
    );

};

export default SearchBar;
